local config = {
  ui_story_30760401_1_1_dialog_content = "Você estava mentindo quando disse que \"<color=#FFB400>A Sombra vai dominar este lugar</color>\", Sr. Vigarista?",
  ui_story_30760401_1_2_dialog_content = "É óbvio. Eu disse isso de forma indireta para deixar as coisas mais interessantes.",
  ui_story_30760401_1_3_dialog_content = "Foi o que pensei. De qualquer forma, eu vim como você pediu. Então, se tem algo a dizer, diga logo.",
  ui_story_30760401_1_4_dialog_content = "Tudo bem então. Vamos para um lugar mais calmo.",
  ui_story_30760401_1_5_dialog_content = "Sou um homem simples com um propósito simples. Estou entediado e não há o que fazer aqui. Aí que você entra.",
  ui_story_30760401_1_6_dialog_content = "Normalmente eu causaria algum problema pra você. Desta vez quero evitar, por isso te chamei aqui.",
  ui_story_30760401_1_7_dialog_content = "Entendi. Você queria que eu viesse aqui só para afastar seu tédio. E se eu recusar você vai achar outra forma de causar problemas?",
  ui_story_30760401_1_8_dialog_content = "Bingo.",
  ui_story_30760401_1_9_dialog_content = "Então, por que você está sendo tão honesto sobre isso de repente... Enfim, se tiver algo que eu possa te ajudar, não hesite em perguntar.",
  ui_story_30760401_1_10_dialog_content = "Vamos jogar um <color=#FFB400>jogo de adivinhação</color>, Navegador, com suas habilidades psíquicas.",
  ui_story_30760401_1_11_dialog_content = "Eu não sabia que minhas habilidades seriam usadas para diversão e jogatina... O que eu devo adivinhar?",
  ui_story_30760401_1_12_dialog_content = "Vejamos… Na primeira rodada, me diga quando o <color=#FFB400>passarinho</color> atrás da porta vai embora.",
  ui_story_30760401_1_13_dialog_content = "Passarinho atrás da porta? Eu vejo um pedaço de tecido verde. É a <color=#FFB400>Dove</color>?",
  ui_story_30760401_1_14_option_content = "Acho que ele vai embora logo.",
  ui_story_30760401_1_15_dialog_content = "Afinal de contas, Dove geralmente está bastante ocupada. Mesmo se ela tentar enrolar, não pode ficar lá por muito tempo.",
  ui_story_30760401_1_16_dialog_content = "<color=#e8d9bb>Um tempo depois...</color>",
  ui_story_30760401_1_17_dialog_content = "O passarinho não planeja ir embora.",
  ui_story_30760401_1_18_dialog_content = "Bem, como uma pequena punição, que tal você espantá-lo?",
  ui_story_30760401_1_19_option_content = "Acho que o passarinho não vai embora logo.",
  ui_story_30760401_1_20_dialog_content = "Afinal, Dove adora ficar à toa.",
  ui_story_30760401_1_21_dialog_content = "Após um tempo...",
  ui_story_30760401_1_22_dialog_content = "O passarinho não planeja ir embora.",
  ui_story_30760401_1_23_dialog_content = "Bom, parece que você tinha razão. Como punição, vou espantar o passarinho.",
  ui_story_30760401_1_24_dialog_content = "Por que essa punição de repente? E por que espantar a Dove?",
  ui_story_30760401_1_25_dialog_content = "Olhe como seu manto balança. Ela claramente está com medo de você!",
  ui_story_30760401_1_26_dialog_content = "Ela vai ficar na frente de outras pessoas que entrarem e saírem da porta. E não quero que ela escute nossa conversa.",
  ui_story_30760401_1_27_dialog_content = "Não, não precisa. Eu...",
  ui_story_30760401_1_28_dialog_content = "Dove, ignore-o!",
  ui_story_30760401_1_29_dialog_content = "Sério? Para a sua própria segurança, garotinha, é melhor não espiar.",
  ui_story_30760401_1_30_dialog_content = "Não estou espiando. Só estou enrolando. Não, quer dizer... Descansando!",
  ui_story_30760401_1_A1_dialog_content = "Buá! Você foi injusto comigo!",
  ui_story_30760401_1_31_dialog_content = "Isso está indo longe demais! Vou te derrotar nesse jogo para vingar a Dove!",
  ui_story_30760401_1_32_dialog_content = "Tudo bem, vamos continuar. Sua segunda predição... Este local está <color=#FFB400>limpo</color> ou <color=#FFB400>sujo</color>?",
  ui_story_30760401_1_33_dialog_content = "Não preciso fazer uma predição dessa vez. Os auxiliares na Colossus cuidam da limpeza.",
  ui_story_30760401_1_34_dialog_content = "O que são eles?",
  ui_story_30760401_1_35_dialog_content = "São dispositivos que podem realizar todos os tipos de tarefas pra mim, como ir até os Geradores pegar energia.",
  ui_story_30760401_1_36_option_content = "Esse local deve estar limpo.",
  ui_story_30760401_1_37_dialog_content = "Então por que está sujo aqui?",
  ui_story_30760401_1_38_dialog_content = "Esse cantinho... Talvez não tenha sido limpo.",
  ui_story_30760401_1_39_option_content = "Acho que... poderia estar mais limpo.",
  ui_story_30760401_1_40_dialog_content = "É verdade. Os cantos estão sujos.",
  ui_story_30760401_1_41_dialog_content = "PlayerName, limpe isto agora. É obvio, eu vou ajudar.",
  ui_story_30760401_1_42_dialog_content = "Espera aí. Por quê?",
  ui_story_30760401_1_43_dialog_content = "Porque meus tentáculos odeiam poeira. Eles estavam querendo... protestar.",
  ui_story_30760401_1_44_dialog_content = "Tudo bem. Então, por favor, vamos evitar essa ameaça.",
  ui_story_30760401_1_45_dialog_content = "<color=#e8d9bb>Após uma sessão de limpeza meticulosa...</color>",
  ui_story_30760401_1_46_dialog_content = "Quando você disse que ia ajudar, eu não achei que fosse ficar borrifando água por aí com seus tentáculos!",
  ui_story_30760401_1_47_dialog_content = "Bem, eu achei que você estava fazendo um trabalho tão bom que não quis atrapalhar.",
  ui_story_30760401_1_48_dialog_content = "Então, para a terceira predição, <color=#FFB400>vamos preparar algo para algum transeunte que possa passar por aqui</color>.",
  ui_story_30760401_1_49_dialog_content = "Transeuntes?",
  ui_story_30760401_1_50_dialog_content = "Sim. Sem saber quem pode aparecer, cada um coloca um <color=#FFB400>presente</color> nesta mesa.",
  ui_story_30760401_1_51_dialog_content = "E aí pedimos ao transeunte pra escolher um pra ele levar.",
  ui_story_30760401_1_52_dialog_content = "Entendi. Então temos que adivinhar quem pode aparecer?",
  ui_story_30760401_1_53_dialog_content = "Eu vou começar. Primeiro, um pano de veludo escuro luxuoso. Depois, um castiçal, rosas e um bom suco.",
  ui_story_30760401_1_54_dialog_content = "Espere aí! Onde você arranjou todas essas coisas? Eu não me lembro de vê-las na Colossus.",
  ui_story_30760401_1_55_dialog_content = "Há vários lugares para guardar coisas. No meu chapéu, capa, tentáculos...",
  ui_story_30760401_1_56_dialog_content = "Não me interessa onde você as pegou, mas isso não é trapaça? Você disse que era um presente.",
  ui_story_30760401_1_57_dialog_content = "Não se preocupe. Eu prometo cumprir as regras. O único presente que vou oferecer é este <color=#FFB400>bom suco</color>.",
  ui_story_30760401_1_58_dialog_content = "Em termos de valor e sabor, é o melhor suco disponível. Usado só para entreter os convidados mais ilustres.",
  ui_story_30760401_1_59_dialog_content = "Os outros itens estão aqui só para encher a mesa e fazer o suco parecer mais como um presente.",
  ui_story_30760401_1_60_dialog_content = "<color=#FFB400>Lembre-se deste detalhe.</color>",
  ui_story_30760401_1_61_dialog_content = "O que você está preparando?",
  ui_story_30760401_1_62_dialog_content = "(Um presente? Não tenho nada de valor comigo...)",
  ui_story_30760401_1_63_dialog_content = "(Minha única vantagem agora é saber que há mais garotas nesta Colossus do que garotos!)",
  ui_story_30760401_1_64_option_content = "Coloque uma caneta na mesa.",
  ui_story_30760401_1_65_dialog_content = "<color=#e8d9bb>Um tempo depois...</color>",
  ui_story_30760401_1_66_dialog_content = "Hã? Você quer que eu escolha um desses dois presentes? Eu posso mesmo pegar um?",
  ui_story_30760401_1_67_dialog_content = "Como não gosto de suco, vou pegar esse.",
  ui_story_30760401_1_68_dialog_content = "(Como imaginava, Vice escolheu o presente que eu preparei!)",
  ui_story_30760401_1_69_dialog_content = "Parece que você ganhou.",
  ui_story_30760401_1_70_option_content = "Coloque umas sobremesas na mesa.",
  ui_story_30760401_1_71_dialog_content = "<color=#e8d9bb>Um tempo depois...</color>",
  ui_story_30760401_1_72_dialog_content = "Um presente?",
  ui_story_30760401_1_73_dialog_content = "Hum... Bem... Acho que vai ser esse...",
  ui_story_30760401_1_74_dialog_content = "Uma garota com asas está passando. Embora hesite, ela, por fim, pega as sobremesas que você preparou.",
  ui_story_30760401_1_75_dialog_content = "Parece que você ganhou.",
  ui_story_30760401_1_76_dialog_content = "Agora para a <color=#FFB400>última predição</color>, que por acaso é a mais importante. Preste bem atenção.",
  ui_story_30760401_1_77_dialog_content = "<color=#FFB400>Quem vai ser o próximo a entrar nesse local?</color>",
  ui_story_30760401_1_78_dialog_content = "De novo? Como eu vou saber isso? Isso não é um pouco difícil?",
  ui_story_30760401_1_79_dialog_content = "Da última vez era alguém passando, agora é entrando. Como dono da Colossus, você precisa conhecer todos a bordo.",
  ui_story_30760401_1_80_dialog_content = "Na verdade, você fez um bom trabalho agora.",
  ui_story_30760401_1_81_dialog_content = "Bem, deixe-me pensar primeiro.",
  ui_story_30760401_1_82_dialog_content = "Claro. Nós dois precisamos de tempo para pensar nisso.",
  ui_story_30760401_1_83_dialog_content = "(Bem, de acordo com a lógica de agora...)",
  ui_story_30760401_1_84_option_content = "Eu acho...",
  ui_story_30760401_1_85_dialog_content = "Hã? Onde está Kleken? Eu olhei pra baixo por um momento e agora ele desapareceu!",
  ui_story_30760401_1_86_dialog_content = "Ele está lá fora? Será que vai tentar trapacear?",
  ui_story_30760401_1_87_dialog_content = "Bem, aqui é bem legal. Eu inicialmente pensei em vir para fazer uma visita casual. Eu não esperava que você fosse <color=#FFB400>tão gentil</color>.",
  ui_story_30760401_1_88_dialog_content = "(Se-Se-Senhor Sombrio...!?)",
  ui_story_30760401_1_89_dialog_content = "É tranquilo. Posso curtir minha privacidade. <color=#FFB400>Não há pessoas insignificantes na minha porta</color>. De fato, um belo lugar. Bom trabalho.",
  ui_story_30760401_1_90_dialog_content = "Eu, eu só...",
  ui_story_30760401_1_91_dialog_content = "Até o piso está limpo. <color=#FFB400>Os cantos foram limpos também</color>?",
  ui_story_30760401_1_92_dialog_content = "(Isso quer dizer...)",
  ui_story_30760401_1_93_dialog_content = "<color=#FFB400>Uma toalha de mesa de veludo, suco...</color> Você saiu perguntando sobre minhas coisas preferidas, né?",
  ui_story_30760401_1_94_dialog_content = "Você é mesmo bem interessante, PlayerName.",
  ui_story_30760401_1_95_dialog_content = "(Kleken tramou isso em segredo desde o início!?)",
  ui_story_30760401_1_96_dialog_content = "(Você não poderia só dizer que Istvan ia fazer uma visita!?)",
  ui_story_30760401_1_97_dialog_content = "É óbvio. Eu propositalmente disse isso de forma indireta para deixar as coisas mais interessantes.",
  ui_story_30760401_1_98_dialog_content = "(Ah... Foi isso que ele quis dizer?)",
  ui_story_30760401_1_99_dialog_content = "Ótimo. Posso ver sua sinceridade. Então acredito que você não vai me desapontar nesta conversa que teremos agora.",
  ui_story_30760401_1_100_dialog_content = "Hã? O quê!?",
  ui_story_30760301_1_1_dialog_content = "O que eu faço com esse <color=#FFB400>Mapa de Dibury</color>? Eu não faço ideia.",
  ui_story_30760301_1_2_dialog_content = "É bem simples. Você pega uma carta de classe após selecionar uma peça.",
  ui_story_30760301_1_3_dialog_content = "Eu peguei a carta de classe Civil.",
  ui_story_30760301_1_4_dialog_content = "Que sorte a minha, peguei a carta Vigarista.",
  ui_story_30760301_1_5_dialog_content = "Espera aí. Essa carta de classe está neste jogo? Você não está trapaceando, né?",
  ui_story_30760301_1_6_dialog_content = "É claro que não. Veja por si próprio.",
  ui_story_30760301_1_7_dialog_content = "Hum, <color=#FFB400>realmente está escrito Vigarista na carta</color>.",
  ui_story_30760301_1_8_dialog_content = "Encontramos bandidos. É hora de jogar o dado. Você precisa que sua Estratégia e Combate sejam maior que 6.",
  ui_story_30760301_1_9_dialog_content = "Estratégia 8, Combate 9! Consegui!",
  ui_story_30760301_1_10_dialog_content = "Estratégia 13, Combate 4! Acho que vou ter que pegar uma carta de Evento.",
  ui_story_30760301_1_11_dialog_content = "A carta de Evento diz: “O seu documento secreto foi confiscado e você é jogado numa masmorra”.",
  ui_story_30760301_1_12_dialog_content = "Toda vez que eu vejo essa coisa, sempre me faz lembrar de <color=#FFB400>de uma experiência anterior</color>. Gostaria de ouvir sobre isso?",
  ui_story_30760301_1_13_option_content = "Pode falar.",
  ui_story_30760301_1_14_dialog_content = "Parece que você se interessou. Terei que fazer um bom trabalho para contar isso.",
  ui_story_30760301_1_15_option_content = "Não mesmo. Por que você vai me contar uma história de repente?",
  ui_story_30760301_1_16_dialog_content = "É, isso não vai dar certo. Confie em mim, é uma boa história. Acho que vou ter que te obrigar a ouvir.",
  ui_story_30760301_1_17_dialog_content = "<color=#e8d9bb>Em uma cavidade subterrânea coberta por destroços</color>",
  ui_story_30760301_1_18_dialog_content = "Se eu tiver que morrer assim, que seja. É só que...",
  ui_story_30760301_1_19_dialog_content = "Tem alguém aí? Por favor, nos ajude!",
  ui_story_30760301_1_20_dialog_content = "Crianças, não fiquem nos meus pés.",
  ui_story_30760301_1_21_dialog_content = "Estamos com medo!!!",
  ui_story_30760301_1_22_dialog_content = "Não se mexe. Tem um buraco aí.",
  ui_story_30760301_1_24_dialog_content = "Você é o Senhor Sombrio?",
  ui_story_30760301_1_25_dialog_content = "Não, não sou. Pode me chamar de Kleken ou Trapaceiro.",
  ui_story_30760301_1_26_dialog_content = "O que fazemos agora, Sr. Trapeceiro?",
  ui_story_30760301_1_27_dialog_content = "Bem, podemos jogar um pouco. Eu tenho uma coisa aqui. Eu trouxe por acaso este <color=#FFB400>Mapa de Dibury</color> comigo. É melhor do que ficar sentado sem fazer nada.",
  ui_story_30760301_1_28_dialog_content = "Uau, que legal!! Por que você tem esse jogo com você?",
  ui_story_30760301_1_29_dialog_content = "Eu comprei várias coisas vindo pra cá.",
  ui_story_30760301_1_30_dialog_content = "Espera aí!",
  ui_story_30760301_1_31_dialog_content = "Qual o sentido desta lembrança aleatória?",
  ui_story_30760301_1_32_dialog_content = "É uma história sobre mim e as garotinhas enterradas no subterrâneo.",
  ui_story_30760301_1_33_dialog_content = "Não, não. Eu quero saber quem são as garotinhas e o que você quis dizer com rastejar sobre seus pés.",
  ui_story_30760301_1_34_dialog_content = "Por que pegar o Mapa de Dibury? E o que você quis dizer com comprar muito no caminho até lá?",
  ui_story_30760301_1_35_dialog_content = "Bem, vou começar do começo.",
  ui_story_30760301_1_36_dialog_content = "<color=#e8d9bb>Cerca de um ano atrás...</color>",
  ui_story_30760301_1_37_dialog_content = "Você ouviu falar dos <color=#FFB400>bandidos</color> nos limites de Umbraton?",
  ui_story_30760301_1_38_dialog_content = "Eu sei.",
  ui_story_30760301_1_39_dialog_content = "Eles sequestraram duas garotinhas associadas à nossa organização e pediram pra eu negociar com eles.",
  ui_story_30760301_1_40_dialog_content = "Mas eu tenho que ir a uma reunião organizada pela Guilda hoje, algo que eles já sabem.",
  ui_story_30760301_1_41_dialog_content = "Os bandidos não sabem como eu me pareço, então eu quero que você resolva isso no meu lugar. Afinal, você é muito experiente na arte da enganação.",
  ui_story_30760301_1_42_dialog_content = "Você quer que eu finja ser você? Interessante. Entendi.",
  ui_story_30760301_1_43_dialog_content = "Tanto faz se for papel ou comida, leve o tanto que precisar. Tem carne-seca e pão na mesa. Pegue.",
  ui_story_30760301_1_44_dialog_content = "Você é o líder da Gangue Istvan?",
  ui_story_30760301_1_45_dialog_content = "Onde estão as reféns? Deixe-me ver se elas estão seguras.",
  ui_story_30760301_1_46_dialog_content = "Estão descansando ali. Não se preocupe, temos algo para entreter suas garotas.",
  ui_story_30760301_1_48_dialog_content = "Me diga o que quer para libertá-las. Cabe a você decidir.",
  ui_story_30760301_1_49_dialog_content = "Só assine este documento e eu deixo elas irem.",
  ui_story_30760301_1_51_dialog_content = "“Transferir Direitos”.",
  ui_story_30760301_1_52_dialog_content = "Tudo bem. Assinado.",
  ui_story_30760301_1_53_dialog_content = "Você é bem rápido. Tem certeza de que leu direito?",
  ui_story_30760301_1_54_dialog_content = "Diz que os direitos da Gangue Istvan de cooperar com a Guilda serão transferidos para você.",
  ui_story_30760301_1_55_dialog_content = "Você decidiu fazer esse sequestro hoje para sabotar a reunião entre a Gangue Istvan e a Guilda, né?",
  ui_story_30760301_1_56_dialog_content = "Exato. É animador poder conversar com alguém tão intuitivo. Você com certeza merece ficar no comando da Gangue Istvan.",
  ui_story_30760301_1_57_dialog_content = "Espere aí. Desde quando o Senhor Sombrio tem filhas!?",
  ui_story_30760301_1_58_dialog_content = "É claro que ele não tem. Talvez eles tenham coletado informação errada de algum lugar. Por isso o engano.",
  ui_story_30760301_1_59_dialog_content = "Enfim, deixe-me continuar a história.",
  ui_story_30760301_1_60_dialog_content = "Sim, tudo assinado, de fato.",
  ui_story_30760301_1_61_dialog_content = "Agora que você já assinou como pedimos... As reféns estão naquela cabana. Fique à vontade para buscá-las.",
  ui_story_30760301_1_62_dialog_content = "Então, os bandidos deixaram você pegar as reféns e ir embora?",
  ui_story_30760301_1_63_dialog_content = "O que você faria se estivesse no lugar deles? Você nos deixaria ir?",
  ui_story_30760301_1_64_option_content = "Eu deixaria, como combinado.",
  ui_story_30760301_1_65_dialog_content = "Afinal, você assinou o contrato, como solicitado. Se eu não deixasse, isso acabaria com a minha credibilidade.",
  ui_story_30760301_1_66_dialog_content = "Esses bandidos não se importam com credibilidade.",
  ui_story_30760301_1_67_option_content = "Óbvio que eu não deixaria você ir.",
  ui_story_30760301_1_68_dialog_content = "Se você revidasse ou rasgasse o acordo no final, o sequestro teria sido em vão.",
  ui_story_30760301_1_69_dialog_content = "Se o Senhor Sombrio tivesse assinado o acordo, a Gangue Istvan jamais quebraria sua promessa. É isso o que você chama de credibilidade.",
  ui_story_30760301_1_70_dialog_content = "Então, você entrou mesmo na cabana? Você não estava com medo de ser uma armadilha?",
  ui_story_30760301_1_71_dialog_content = "É claro, eu tinha que entrar. A segurança das reféns era minha prioridade.",
  ui_story_30760301_1_72_dialog_content = "E o que aconteceu?",
  ui_story_30760301_1_73_dialog_content = "Quando fui desamarrar as reféns, encontrei duas garotinhas dormindo. E aí...",
  ui_story_30760301_1_74_dialog_content = "<size=50>Bum!</size>",
  ui_story_30760301_1_75_dialog_content = "Eles detonaram uma bomba subterrânea!",
  ui_story_30760301_1_76_dialog_content = "Uma bomba? Alguém se feriu?",
  ui_story_30760301_1_77_dialog_content = "Então é aí onde a história sobre você e as garotinhas enterradas em destroços começa?",
  ui_story_30760301_1_78_dialog_content = "Sim. Embora não tenha sido uma explosão grande, eu ainda usei muita força para me defender completamente.",
  ui_story_30760301_1_79_dialog_content = "Não conseguimos sair imediatamente porque eu precisava me recuperar.",
  ui_story_30760301_1_80_dialog_content = "Ok. Mas você disse que pegou o Mapa de Dibury? Vocês jogaram mesmo?",
  ui_story_30760301_1_81_dialog_content = "Sim. Mas após começarmos, elas engoliram o dado de alguma forma, e aí tivemos que conversar naqueles escombros subterrâneos.",
  ui_story_30760301_1_82_dialog_content = "Se me lembro bem, você se uniu à Gangue Istvan há pouco tempo.",
  ui_story_30760301_1_83_dialog_content = "Oh, você nos reconheceu. Nós somos <color=#FFB400>Patty</color> e <color=#FFB400>Patsy</color>.",
  ui_story_30760301_1_84_dialog_content = "Como vocês foram capturadas? Eles não parecem muito fortes.",
  ui_story_30760301_1_85_dialog_content = "Estávamos brincando do lado de fora e desmaiamos de fome na beira da pista. Quando abrimos os olhos, já tínhamos sido sequestradas.",
  ui_story_30760301_1_86_dialog_content = "Isso explica por que estão sempre deitadas no chão. O Senhor Sombrio deve ter feito essa comida para vocês.",
  ui_story_30760301_1_87_dialog_content = "Carne-seca!",
  ui_story_30760301_1_88_dialog_content = "Pão!",
  ui_story_30760301_1_89_dialog_content = "Nham, nham.",
  ui_story_30760301_1_90_dialog_content = "Estamos cheias!",
  ui_story_30760301_1_91_dialog_content = "Então vamos trabalhar. Vá pra trás um pouco. Eu preciso tirar os destroços acima de nós.",
  ui_story_30760301_1_92_dialog_content = "Que tentáculos grandes e poderosos! De onde eles surgiram?",
  ui_story_30760301_1_93_dialog_content = "Isso não importa. <color=#FFB400>Imagine que é uma ilusão</color>. Agora, é sua vez de trabalhar duro.",
  ui_story_30760301_1_94_dialog_content = "Provavelmente só tem alguns bandidos guardando a base deles. Eu sei onde eles estão. Vamos lá mordê-los.",
  ui_story_30760301_1_95_dialog_content = "Depois, tomamos a base dele com facilidade. Final feliz.",
  ui_story_30760301_1_96_dialog_content = "Espere aí. Nossa, agora você me fez falar!",
  ui_story_30760301_1_97_dialog_content = "Por que você acha que só tinham alguns bandidos guardando a base deles?",
  ui_story_30760301_1_98_dialog_content = "Simples, porque o chefe deles foi para a Guilda com seus lacaios e o acordo.",
  ui_story_30760301_1_99_dialog_content = "O acordo que você assinou? Ele não deve ter sido aceito como legítimo.",
  ui_story_30760301_1_100_dialog_content = "Não, eu assinei o nome do Istvan e usei o selo dele.",
  ui_story_30760301_1_101_dialog_content = "Aquele documento de fato era válido, infelizmente.",
  ui_story_30760301_1_102_dialog_content = "<color=#e8d9bb>Na reunião secreta</color>",
  ui_story_30760301_1_103_dialog_content = "Quem são vocês, e o que estão fazendo aqui, estranhos?",
  ui_story_30760301_1_104_dialog_content = "Você é o chefe da Guilda? A partir de hoje, nossa gangue vai trabalhar com vocês.",
  ui_story_30760301_1_105_dialog_content = "Aqui está o “Transferir Direitos”, assinado pelo próprio Istvan.",
  ui_story_30760301_1_106_dialog_content = "Um acordo? Esse não é o <color=#FFB400>Mapa de Dibury</color>? Oh, é do mesmo lote que publicamos recentemente.",
  ui_story_30760301_1_107_dialog_content = "Mas claramente está escrito nesse papel que... Não é possível! <color=#FFB400>Deve ser uma ilusão</color>!",
  ui_story_30760301_1_108_dialog_content = "Droga! Istvan nos enganou!? Como!?",
  ui_story_30760301_1_109_dialog_content = "O Sr. Istvan está aqui com um grupo de assistentes. Gostaria de vê-lo?",
  ui_story_30760301_1_110_dialog_content = "Você veio até aqui. Por favor, sente-se.",
  ui_story_30760301_1_111_dialog_content = "E então os bandidos foram levados direto para as mãos do Senhor Sombrio. Final feliz de novo.",
  ui_story_30760301_1_112_dialog_content = "Os bandidos pegaram mesmo o Mapa de Dibury? Como eles confundiram com um acordo?",
  ui_story_30760301_1_113_dialog_content = "Eles confirmaram mais de uma vez. Se fosse você, cairia no meu truque?",
  ui_story_30760301_1_114_option_content = "Bem, se você tivesse entregado pra mim... Talvez?",
  ui_story_30760301_1_115_dialog_content = "Parece que você me conhece um pouco.",
  ui_story_30760301_1_116_option_content = "De jeito nenhum! Eu seria capaz de saber!",
  ui_story_30760301_1_117_dialog_content = "Não é ruim ter tal confiança.",
  ui_story_30760301_1_118_dialog_content = "Sendo assim, dê uma olhada nisso.",
  ui_story_30760301_1_119_dialog_content = "Hã? Essa não é a carta de classe que você pegou no começo?",
  ui_story_30760301_1_120_dialog_content = "O que há nela?",
  ui_story_30760301_1_121_dialog_content = "Hum... Classe, <color=#FFB400>Gângster</color>? Como isso é possível!?",
  ui_story_30760301_1_122_dialog_content = "Mas estava escrito <color=#FFB400>Vigarista</color> antes! Você trapaceou e trocou cartas?",
  ui_story_30760301_1_123_dialog_content = "Não. Em primeiro lugar, não existe Vigarista no jogo do Mapa de Dibury.",
  ui_story_30760301_1_124_dialog_content = "<color=#FFB400>O que você viu antes... Imagine que é uma ilusão.</color>",
  ui_story_30760601_1_1_dialog_content = "O sol e a areia escaldantes...",
  ui_story_30760601_1_2_dialog_content = "Algo não parece certo... <color=#FFB400>Esse ideal</color>... É muito suspeito...",
  ui_story_30760601_1_3_dialog_content = "Por que eu tô indo pra lá e pra cá num dia tão quente?",
  ui_story_30760601_1_4_dialog_content = "E fazendo entregas na casa de <color=#FFB400>Kleken</color>?!",
  ui_story_30760601_1_5_dialog_content = "Kleken!",
  ui_story_30760601_1_6_dialog_content = "Ah, ei, você está de volta! Você terminou a entrega?",
  ui_story_30760601_1_7_dialog_content = "Terminei... Você ...",
  ui_story_30760601_1_8_dialog_content = "Quem é você?",
  ui_story_30760601_1_9_dialog_content = "Aww... Que dó, você tá indo para cima e para baixo na praia fazendo entregas para mim o dia todo.",
  ui_story_30760601_1_10_dialog_content = "Parece que o calor tá afetando sua cabeça e você nem lembra com quem tava tão preocupado...",
  ui_story_30760601_1_11_dialog_content = "Quem mais estaria aqui, além de mim?",
  ui_story_30760601_1_12_dialog_content = "K-Kleken?! Você sempre pareceu tão jovem?!",
  ui_story_30760601_1_13_dialog_content = "Parabéns! Você descobriu mais uma nova verdade.",
  ui_story_30760601_1_14_dialog_content = "Quando o tempo tá quente, eu viro um <color=#FFB400>Kleken completamente diferente</color>.",
  ui_story_30760601_1_15_dialog_content = "Por que não senta e faz uma pausa? Quer um pouco de água?",
  ui_story_30760601_1_16_dialog_content = "Ainda tenho algumas coisas que queria que você entregasse.",
  ui_story_30760601_1_17_dialog_content = "De jeito nenhum! Não vou mais te ajudar a entregar nada! Faz sozinho!",
  ui_story_30760601_1_18_dialog_content = "Nossa, PlayerName, não precisa gritar assim. Foi você que prometeu me ajudar a \"terminar meus negócios\".",
  ui_story_30760601_1_19_dialog_content = "Se você esqueceu, eu não ligo de refrescar um pouco sua memória...",
  ui_story_30760601_1_20_dialog_content = "F-fica aí! Eu vou descobrir como você me enganou por conta própria!",
  ui_story_30760601_1_21_dialog_content = "Já ouviu a história do herói que foi ao palácio subaquático e derrotou um monstro marinho? É uma história muito legal.",
  ui_story_30760601_1_22_dialog_content = "É por isso que você devia cuidar do seu lado esquerdo também...",
  ui_story_30760601_1_23_dialog_content = "Graagh!",
  ui_story_30760601_1_24_dialog_content = "Finalmente... acabei...",
  ui_story_30760601_1_25_dialog_content = "Então por que eu passei por esse tipo de perigo?!",
  ui_story_30760601_1_26_dialog_content = "Pra me ajudar a conseguir estes produtos importantes, é claro.",
  ui_story_30760601_1_27_dialog_content = "Não, eu achei que você teve uns probleminhas enquanto se preparava pro Monarca do Oceano...",
  ui_story_30760601_1_28_dialog_content = "E aí você me chamou...",
  ui_story_30760601_1_29_dialog_content = "Quem ia imaginar que você me faria encontrar Eclipsitas e me levaria pro meio de um monte deles?!",
  ui_story_30760601_1_30_dialog_content = "...",
  ui_story_30760601_1_31_dialog_content = "Ei, por que você tá tão quieto? Não vai se explicar?",
  ui_story_30760601_1_32_dialog_content = "Que explicações você quer? Vou deixar isso aqui rapidinho...",
  ui_story_30760601_1_33_dialog_content = "Você... tá bem?",
  ui_story_30760601_1_34_dialog_content = "Estou bem. Quase caí agora, só isso.",
  ui_story_30760601_1_35_dialog_content = "(Como alguém tão ágil como Kleken \"quase cai\"? Ele...)",
  ui_story_30760601_1_36_dialog_content = "Está suando?",
  ui_story_30760601_1_37_dialog_content = "Claro que tô... Tá um calorão aqui...",
  ui_story_30760601_1_38_dialog_content = "E ainda assim você tá usando roupas grossas... Você gastou toda aquela energia lutando contra os Eclipsitas com essa roupa agorinha mesmo.",
  ui_story_30760601_1_39_dialog_content = "Mas o mais importante... Você se machucou na luta?",
  ui_story_30760601_1_40_dialog_content = "Parece que me descobriu. Nada mal, PlayerName.",
  ui_story_30760601_1_41_dialog_content = "Desculpe... Eu não estou me sentindo bem...",
  ui_story_30760601_1_42_dialog_content = "Eu sinto muito mesmo... Mas acho que não consigo acabar isso sozinho...",
  ui_story_30760601_1_43_dialog_content = "Pra falar a verdade, é a primeira vez que te vejo arriscar a vida assim por um trabalho...",
  ui_story_30760601_1_44_dialog_content = "O que você pegou dos Eclipsitas?",
  ui_story_30760601_1_45_dialog_content = "Pode abrir e ver. Vá em frente, abre algumas dessas caixas e dê uma olhada no que tem dentro.",
  ui_story_30760601_1_46_dialog_content = "Bom...",
  ui_story_30760601_1_47_dialog_content = "O que é isso, uma caixa de tecido?",
  ui_story_30760601_1_48_dialog_content = "É uma caixa cheia de mercadorias valiosas.",
  ui_story_30760601_1_49_dialog_content = "\"Mercadoria valiosa\"? Quer dizer que vocês foram roubados por Eclipsitas?",
  ui_story_30760601_1_50_dialog_content = "Isso não é só um trabalho, tem a ver com meus ideais... com os palácios de nossos corações.",
  ui_story_30760601_1_51_dialog_content = "Mas não tenho mais como entregar isso pros mercadores de Umbraton...",
  ui_story_30760601_1_52_dialog_content = "E eles vão sofrer por causa disso, com certeza.",
  ui_story_30760601_1_53_dialog_content = "Quando penso assim, minha consciência quase me despedaça.",
  ui_story_30760601_1_54_dialog_content = "Para de falar sobre seus ideais!",
  ui_story_30760601_1_55_dialog_content = "Eu carrego as caixas! Vamos sair daqui antes que mais Eclipsitas apareçam!",
  ui_story_30760601_1_56_dialog_content = "Não... Pode ir na frente. Tem uma pessoa no lado sul da praia, entregue isso a ela dentro de meia hora.",
  ui_story_30760601_1_57_dialog_content = "Não deve ser um problema para você. Acho que você vai chegar a tempo, sua velocidade é boa!",
  ui_story_30760601_1_58_dialog_content = "Aqui, pegue e corra. Continue correndo e não olhe pra trás.",
  ui_story_30760601_1_59_dialog_content = "Certifique-se de que isso chegue às mãos daquela pessoa.",
  ui_story_30760601_1_60_dialog_content = "Hã? E você?",
  ui_story_30760601_1_61_dialog_content = "Gaah... Graaah...",
  ui_story_30760601_1_62_dialog_content = "Vou impedir elas...",
  ui_story_30760601_1_63_dialog_content = "Kleken?!",
  ui_story_30760601_1_64_dialog_content = "Rápido, PlayerName! Corre!",
  ui_story_30760601_1_65_dialog_content = "Graagh!",
  ui_story_30760601_1_66_dialog_content = "E assim, o bravo guerreiro correu, levando suas esperanças ao destino.",
  ui_story_30760601_1_67_dialog_content = "E quando ele teve problemas, o monstro do mar branco veio em seu socorro.",
  ui_story_30760601_1_68_dialog_content = "Sim... Parece uma história maravilhosa. Quanto ao nome...",
  ui_story_30760601_1_69_dialog_content = "Gaah... Graaah...",
  ui_story_30760601_1_70_dialog_content = "Está longe? Será que falta muito?",
  ui_story_30760601_1_71_dialog_content = "Ele se sacrificou sem hesitar... Tenho que entregar essas coisas pra aquela pessoa!",
  ui_story_30760601_1_72_dialog_content = "Eu consigo... E aí, vou chamar outras pessoas para salvar ele!",
  ui_story_30760601_1_73_dialog_content = "*Ofegante* Eu... Eu consegui...",
  ui_story_30760601_1_74_dialog_content = "Ah! Você finalmente chegou! Esperei o dia todo!",
  ui_story_30760601_1_75_dialog_content = "Essa mercadoria é muito importante! A entrega é pra você?",
  ui_story_30760601_1_76_dialog_content = "Sim! Hmm, nada mal... Deixa eu dar uma olhada no que temos hoje.",
  ui_story_30760601_1_77_dialog_content = "Não dá tempo! Precisamos voltar e resgatar o Kleken! Ele está cercado por Eclipsitas!",
  ui_story_30760601_1_78_dialog_content = "Hã? Mas o dono da loja recebeu uma mensagem do Kleken há menos de meia hora. Ele disse...",
  ui_story_30760601_1_79_dialog_content = "Ele disse que estava tudo certo e para esperar até a encomenda chegar.",
  ui_story_30760601_1_80_dialog_content = "Hã? Meia hora atrás?",
  ui_story_30760601_1_81_dialog_content = "Não foi logo depois que eu saí?",
  ui_story_30760601_1_82_dialog_content = "Ele também disse que encontrou alguém eficiente para entregar a mercadoria desta vez, e que eu não precisava me preocupar. Você deve ser a pessoa que ele falou.",
  ui_story_30760601_1_83_dialog_content = "Mas você foi meio lento. Pelas nossas contas, você deveria ter chegado há dez minutos.",
  ui_story_30760601_1_84_dialog_content = "Aquele cara ganhou uma fortuna com esse tipo de trabalho. Você deve ganhar bem, já que trabalha para ele, né?",
  ui_story_30760601_1_85_dialog_content = "Você disse \"uma fortuna\"? Os Eclipsitas não roubaram toda essa mercadoria de vocês?",
  ui_story_30760601_1_86_dialog_content = "Do que você está falando? Acabamos de importar essas coisas com o Kleken, só isso...",
  ui_story_30760601_1_87_dialog_content = "Eu... preciso voltar e descobrir a verdade.",
  ui_story_30760601_1_88_dialog_content = "Achei que você fosse ser comido por uma multidão de Eclipsitas!",
  ui_story_30760601_1_89_dialog_content = "Achei que você tivesse querendo proteger algo que você valorizava mais do que a própria vida!",
  ui_story_30760601_1_90_dialog_content = "Achei que você estivesse fraco com o calor e suas feridas!",
  ui_story_30760601_1_91_dialog_content = "Me arrisquei no sol e no calor para entregar a mercadoria, mas aí aquele comerciante me disse...",
  ui_story_30760601_1_92_dialog_content = "Que não tinham sido roubadas dele! Você está roubando essas coisas de outras pessoas para vender pros mercadores?",
  ui_story_30760601_1_93_dialog_content = "Calma, PlayerName. Isso é só um mal-entendido. Deixa eu explicar...",
  ui_story_30760601_1_94_dialog_content = "Quando eu vim aqui e pedi sua ajuda...",
  ui_story_30760601_1_95_dialog_content = "Era porque eu tinha um trabalho importante a fazer, ou seja, eliminar alguns Eclipsitas.",
  ui_story_30760601_1_96_dialog_content = "Nós tivemos mesmo alguns problemas enquanto nos preparávamos pro Monarca do Oceano, uma multidão de Eclipsitas que não queriam sair daqui.",
  ui_story_30760601_1_97_dialog_content = "E eu estava realmente ferido e não ia poder lidar com o calor.",
  ui_story_30760601_1_98_dialog_content = "Eu tava fraco para fazer o trabalho e você me ajudou a terminar. Eu devia te agradecer.",
  ui_story_30760601_1_99_dialog_content = "Mas quando eu perguntei se aquelas eram suas mercadorias, por que você...",
  ui_story_30760601_1_100_dialog_content = "Já disse, tem a ver com os <color=#FFB400>meus ideais</color> e com os <color=#FFB400>palácios nos corações</color>.",
  ui_story_30760601_1_101_dialog_content = "Você estava evitando a pergunta de propósito?!",
  ui_story_30760601_1_102_dialog_content = "Achei que você estava tentando dizer que a mercadoria era importante para realizar seus sonhos ou algo assim!",
  ui_story_30760601_1_103_dialog_content = "Até pensei que vocês estavam economizando dinheiro para construir um palácio!",
  ui_story_30760601_1_104_dialog_content = "Hehe... Nada mal, PlayerName. Você descobriu a verdade ainda mais rápido do que eu esperava.",
  ui_story_30760601_1_105_dialog_content = "Mas se você acha mesmo que só faço isso por dinheiro, está muito enganado.",
  ui_story_30760601_1_106_dialog_content = "Eu estou, mesmo, agindo por interesse dos meus ideais.",
  ui_story_30760601_1_107_dialog_content = "O que isso quer dizer?! Porque eu tenho certeza de que você só tá me usando para ganhar algum dinheiro!",
  ui_story_30760601_1_108_dialog_content = "Você me usou para encontrar os Eclipsitas e para entregar a mercadoria...",
  ui_story_30760601_1_X108_dialog_content = "Mas o mais importante, nenhuma das mercadorias pertencia a vocês.",
  ui_story_30760601_1_X109_dialog_content = "Você já parou para pensar em como os donos originais dessas coisas podem estar preocupados agora?",
  ui_story_30760601_1_X110_dialog_content = "Ou você acha que pode só penhorar tudo o que roubar dos Eclipsitas?",
  ui_story_30760601_1_109_dialog_content = "Chega. De acordo com a investigação da Gangue de Istvan sobre as mercadorias, chegamos à conclusão...",
  ui_story_30760601_1_110_dialog_content = "De que a mercadoria <color=#FFB400>não tem dono original</color>.",
  ui_story_30760601_1_111_dialog_content = "Então você tá querendo dizer que não foi um negócio sujo?",
  ui_story_30760601_1_112_dialog_content = "Isso. Essa é uma informação muito importante, sem ela, você não entenderia minhas intenções.",
  ui_story_30760601_1_113_dialog_content = "Quando receber meu pagamento, será só por eliminar Eclipsitas e nada mais.",
  ui_story_30760601_1_114_dialog_content = "O resto vai direto pra Gangue de Istvan.",
  ui_story_30760601_1_115_dialog_content = "Você pode não saber, mas o Senhor Sombrio gosta muito de realizar \"boas ações\".",
  ui_story_30760601_1_116_dialog_content = "Tá bom...",
  ui_story_30760601_1_117_dialog_content = "Desculpa, admito que te julguei mal.",
  ui_story_30760601_1_118_dialog_content = "Não fale disso.",
  ui_story_30760601_1_119_dialog_content = "Como um golpista, prefiro que desconfiem de mim.",
  ui_story_30760601_1_120_dialog_content = "Por que parece que você tá sendo sarcástico?",
  ui_story_30760601_1_121_dialog_content = "Então o que é esse \"ideal\" que você vive falando? Você disse que estava agindo por interesse dos seus ideais, né?",
  ui_story_30760601_1_122_dialog_content = "Depois de ouvir que você tava vendendo aquelas coisas pro comerciante, pensei que estava fazendo isso por dinheiro...",
  ui_story_30760601_1_123_dialog_content = "Mas usar dinheiro sujo... pra construir um palácio? Bom, pelo menos agora sei que o dinheiro não é sujo.",
  ui_story_30760601_1_124_dialog_content = "O festival.",
  ui_story_30760601_1_125_dialog_content = "Afinal, o Monarca do Oceano ainda é um festival.",
  ui_story_30760601_1_126_dialog_content = "Hã... Eu sei bem que é um festival, que tipo de resposta é essa?",
  ui_story_30760601_1_127_dialog_content = "Não vamos nos precipitar. Quando se trata dos ideais de alguém, precisamos descrevê-los bem pra conquistar os corações dos outros.",
  ui_story_30760601_1_128_dialog_content = "Era uma vez, um herói...",
  ui_story_30760601_1_129_dialog_content = "Ele estava navegando em alto mar em um navio real, em busca de um tesouro lendário...",
  ui_story_30760601_1_130_dialog_content = "Quando, um dia, encontrou um monstro do mar gigante e branco.",
  ui_story_30760601_1_131_dialog_content = "E com isso, ele descobriu um magnífico palácio subaquático.",
  ui_story_30760601_1_132_dialog_content = "Finalmente, ele encontrou seu tesouro, então fez um pacto com a criatura branca para exterminar os violentos monstros marinhos que assolam as águas.",
  ui_story_30760601_1_133_dialog_content = "Esta é uma das minhas histórias favoritas, chama <color=#FFB400>\"Uma Viagem Aventureira\"</color>.",
  ui_story_30760601_1_134_dialog_content = "O palácio de uma história? Mas \"Uma Viagem Aventureira\" não é ficção?",
  ui_story_30760601_1_135_dialog_content = "Ou você está dizendo que tem algo a ver com o Monarca do Oceano?",
  ui_story_30760601_1_136_dialog_content = "Eu vim aqui é para investigar a relação entre os dois.",
  ui_story_30760601_1_137_dialog_content = "Para ver aquele palácio da história.",
  ui_story_30760601_1_138_dialog_content = "Enquanto eu oferecer minha sinceridade a Netuno, ele concederá meu desejo e fará o palácio aparecer diante de mim.",
  ui_story_30760601_1_139_dialog_content = "Ajudar a administrar o Monarca do Oceano é uma forma de mostrar minha sinceridade.",
  ui_story_30760601_1_140_dialog_content = "Parece meio estranho...",
  ui_story_30760601_1_141_dialog_content = "Você acha que essa história é baseada na realidade? Ou você acha que não existe palácio subaquático?",
  ui_story_30760601_1_142_option_content = "Nunca li essa história.",
  ui_story_30760601_1_143_dialog_content = "...",
  ui_story_30760601_1_144_dialog_content = "...",
  ui_story_30760601_1_145_dialog_content = "Que estranho. De repente, não tenho ideia de como continuar neste tópico.",
  ui_story_30760601_1_146_dialog_content = "Mas tudo bem, não importa se você não leu essa história.",
  ui_story_30760601_1_147_option_content = "Eu acredito.",
  ui_story_30760601_1_148_dialog_content = "Pode ser que o palácio da história seja um lugar real.",
  ui_story_30760601_1_149_dialog_content = "Fico feliz que você possa acreditar nisso tão rápido.",
  ui_story_30760601_1_150_dialog_content = "Só espero que os presentes que preparei não te desapontem.",
  ui_story_30760601_1_151_dialog_content = "Presentes?",
  ui_story_30760601_1_152_dialog_content = "Correto. Não é todo dia que encontro alguém tão interessado em meus ideais.",
  ui_story_30760601_1_153_dialog_content = "O mínimo que posso fazer é mostrar gratidão.",
  ui_story_30760601_1_154_option_content = "Eu não acredito nisso não.",
  ui_story_30760601_1_155_dialog_content = "Essa história é uma ficção, não é?",
  ui_story_30760601_1_156_dialog_content = "Quando as pessoas escrevem histórias assim, muitas vezes, fazem alusão a eventos reais.",
  ui_story_30760601_1_157_dialog_content = "A história em si pode ser fictícia, mas pode ser que o autor a tenha inventado com base em vários relatos verdadeiros.",
  ui_story_30760601_1_158_dialog_content = "Este é um dos meus ideais, às vezes está longe de mim, às vezes está muito perto.",
  ui_story_30760601_1_159_dialog_content = "A lenda do Monarca do Oceano, fala de um castelo.",
  ui_story_30760601_1_160_dialog_content = "O castelo na lenda e o palácio na história... Pode haver algum tipo de relação entre os dois.",
  ui_story_30760601_1_161_dialog_content = "De qualquer forma, também quero que você veja por si só, por isso pedi sua ajuda.",
  ui_story_30760601_1_162_dialog_content = "Mas parece que ainda não é a hora certa... Bom, acho que posso tentar um pouco mais.",
  ui_story_30760601_1_163_dialog_content = "O palácio no fundo do mar...",
  ui_story_30760601_1_164_dialog_content = "Mesmo que tudo o que resta sejam ruínas, ainda é uma visão surpreendente...",
  ui_story_30760601_1_165_dialog_content = "Um testamento de uma grande e brilhante civilização que já viveu aqui.",
  ui_story_30760601_1_166_dialog_content = "O palácio? Você... Você realmente invocou o palácio?",
  ui_story_30760601_1_167_dialog_content = "O que acha? Você acredita na existência dele agora?",
  ui_story_30760601_1_168_dialog_content = "Sim, eu...",
  ui_story_30760601_1_169_dialog_content = "Aliás, isso é só uma ilusão. Se você olhar mais de perto, vai ver certinho.",
  ui_story_30760601_1_170_dialog_content = "Eu ia dizer que agora acredito... Mas aí você me interrompeu.",
  ui_story_30760601_1_171_dialog_content = "Hm... Não fique chateado. Criar ilusões para você ver é apenas um dos meus muitos poderes.",
  ui_story_30760601_1_172_dialog_content = "Infelizmente, não posso manter por mais tempo. Afinal, ainda estou muito fraco.",
  ui_story_30760601_1_173_dialog_content = "Espera, você estava descansando muito confortavelmente quando eu voltei...",
  ui_story_30760601_1_174_dialog_content = "Você até trocou pra roupa de banho...",
  ui_story_30760601_1_175_dialog_content = "E ainda pode usar seus poderes assim?",
  ui_story_30760601_1_176_dialog_content = "Além disso, me falaram que o trabalho de hoje foi fácil, segundo você...",
  ui_story_30760601_1_177_dialog_content = "Você está mesmo tão fraco?",
  ui_story_30760601_1_178_dialog_content = "Hmm... Você quer mesmo analisar demais as coisas...",
  ui_story_30760601_1_179_dialog_content = "Ei... Você não estava em pé e bem agora mesmo?",
  ui_story_30760601_1_180_dialog_content = "Espera... Por que tenho a sensação de que você vai me enganar de novo?",
  ui_story_30760601_1_181_dialog_content = "Hmm, mesmo que minhas forças estejam quase no fim, acho que posso aguentar.",
  ui_story_30760601_1_182_dialog_content = "No mínimo, queria dar uma amostra do palácio dos meus sonhos.",
  ui_story_30760601_1_183_dialog_content = "Tudo bem, desculpa por desconfiar de novo... Achei que você ainda tinha um pouco de força, mas parece que não.",
  ui_story_30760601_1_184_dialog_content = "Nunca pensei que você fosse tão determinado...",
  ui_story_30760601_1_185_dialog_content = "Considere isso sua recompensa.",
  ui_story_30760601_1_186_dialog_content = "Hã?",
  ui_story_30760601_1_187_dialog_content = "Simples e precipitado, mas com uma percepção que beira o anormal.",
  ui_story_30760601_1_188_dialog_content = "Você tem um ar de herói.",
  ui_story_30760601_1_189_dialog_content = "E é isso que essa história precisa para ser concluída.",
  ui_story_30760601_1_190_dialog_content = "Como recompensa por me ajudar a entregar aquela mercadoria, decidi deixar você ver estas paisagens espetaculares.",
  ui_story_30760601_1_191_dialog_content = "Assim, também não preciso pagar em dinheiro.",
  ui_story_30760601_1_192_dialog_content = "...",
  ui_story_30760601_1_193_dialog_content = "Você não precisava falar a última parte, Kleken...",
  ui_story_30760601_1_194_dialog_content = "É mesmo? Mas achei que, desde que recebesse uma recompensa, estaria disposto a me ajudar a terminar o meu trabalho?",
  ui_story_30760601_1_195_dialog_content = "Então você quer que eu continue fazendo entregas para você?! Não dá pra deixar esse sentimento durar mais um pouco?!",
  ui_story_30760601_1_196_dialog_content = "Claro que não.",
  ui_story_30760601_1_197_dialog_content = "\"A Entrega Heroica\"... É uma história muito interessante também, não acha?",
  ui_story_30760601_1_198_dialog_content = "Não é uma história real!!",
  ui_story_30760601_1_199_dialog_content = "Eu acabei de pensar nela, na verdade. Espero que goste!"
}
return config
